function priceProduct(g){
 const index=commodityTiers.indexOf(g.id),tier=({textiles:7,metals:13})[g.id]??(index>=0?index:Object.hasOwn(restrictedTiers,g.id)?restrictedTiers[g.id]:resourcePlan.valueTiers[g.id]);
 if(tier===undefined)throw Error('Assign a commodity value tier before listing it.');
 // Physical throughput follows the original lot specification, not the new capital-value ladder.
 const inventoryScale=g.inventoryScale??(g.base>=2000?.08:g.base>=900?.14:g.base>=600?.25:g.handling?.4:1);
 const foundation=['aggregate','water','liquid-water','oxygen','nitrogen','carbon','food','glass','polymers','medicine'];
 const discoveryLevel=foundation.includes(g.id)?0:(g.valueTier>=27||tier>=27?4:g.handling?.length?Math.min(4,Math.max(2,Math.floor(tier/8))):tier>=19?3:tier>=15?2:1);
 return {...g,xp:100*(2**discoveryLevel-1),discoveryLevel,valueTier:tier,inventoryScale,base:Math.round(pricing.entryBase*pricing.growth**tier/pricing.rounding)*pricing.rounding};
}
